mapper.select:
SELECT * FROM t_coupon_inst_${tableSuffix}
WHERE user_id = #{userId} AND region_code = #{regionCode}
ORDER BY created_at DESC

mapper.update:
UPDATE t_coupon_inst_${tableSuffix}
SET status = #{newStatus},
    received_at = #{updatedAt},
    updated_at = #{updatedAt}
WHERE coupon_inst_id = #{couponInstId}
  AND user_id = #{userId}
  AND region_code = #{regionCode}
  AND status = #{oldStatus}

UPDATE t_coupon_inst_${tableSuffix}
SET status = #{newStatus},
    order_id = #{orderId},
    used_at = #{usedAt},
    updated_at = #{updatedAt}
WHERE coupon_inst_id = #{couponInstId}
  AND user_id = #{userId}
  AND region_code = #{regionCode}
  AND status = #{oldStatus}

mapper.select:
SELECT COUNT(*) FROM t_coupon_inst_${tableSuffix}
WHERE template_id = #{templateId} AND user_id = #{userId} AND region_code = #{regionCode}
  AND status IN ('RECEIVED', 'USED', 'REFUNDED')

mapper.update:
UPDATE t_coupon_inst_${tableSuffix}
SET status = #{newStatus},
    order_id = NULL,
    used_at = NULL,
    updated_at = #{updatedAt}
WHERE coupon_inst_id = #{couponInstId}
  AND order_id = #{orderId}
  AND region_code = #{regionCode}
  AND status = #{oldStatus}
